CREATE TABLE ar_bad_type (id INT PRIMARY KEY AUTO_RANDOM);
CREATE TABLE ar_bad_inc (id BIGINT PRIMARY KEY AUTO_INCREMENT AUTO_RANDOM);
CREATE TABLE ar_bad_def (id BIGINT PRIMARY KEY AUTO_RANDOM DEFAULT 7);
CREATE TABLE ar_bad_shard (id BIGINT PRIMARY KEY AUTO_RANDOM(16));
CREATE TABLE ar_bad_incr (id BIGINT PRIMARY KEY AUTO_RANDOM(15,41));
CREATE TABLE ar_no_pk (id BIGINT AUTO_RANDOM);
CREATE TABLE ar_nonclustered (id BIGINT AUTO_RANDOM, PRIMARY KEY (id) NONCLUSTERED);
CREATE TABLE ar_not_first (a INT, id BIGINT AUTO_RANDOM, PRIMARY KEY (a, id) CLUSTERED);
